func TestExtractors_MatchTheLiveResponseShapes(t *testing.T) {
	// Shapes below were read from live responses on 2026-09-07; the values
	// are synthetic.
	t.Run("sleep_stats unwraps individualStats and drops the window-scoped overallStats", func(t *testing.T) {
		s := seriesNamed(t, "sleep_stats")
		raw := json.RawMessage(`{"overallStats":{"averageSleepScore":80},"individualStats":[
			{"calendarDate":"2026-09-06","values":{"sleepScore":81}},
			{"calendarDate":"2026-09-07","values":{"sleepScore":77}}]}`)
		rows, err := s.extract(raw, mustParseCivilDay("2026-09-07"))
		if err != nil {
			t.Fatalf("extract: %v", err)
		}
		if len(rows) != 2 || rows[0].id != "2026-09-06" || rows[1].id != "2026-09-07" {
			t.Fatalf("rows = %+v", rows)
		}
	})

	t.Run("resting_hr descends into allMetrics.metricsMap", func(t *testing.T) {
		s := seriesNamed(t, "resting_hr")
		raw := json.RawMessage(`{"allMetrics":{"metricsMap":{"WELLNESS_RESTING_HEART_RATE":[
			{"calendarDate":"2026-09-07","value":51.0}]}},"groupedMetrics":null}`)
		rows, err := s.extract(raw, civilDay{})
		if err != nil {
			t.Fatalf("extract: %v", err)
		}
		if len(rows) != 1 || rows[0].id != "2026-09-07" {
			t.Fatalf("rows = %+v", rows)
		}
	})

	t.Run("resting_hr with no readings yields an empty window rather than an error", func(t *testing.T) {
		s := seriesNamed(t, "resting_hr")
		rows, err := s.extract(json.RawMessage(`{"allMetrics":{"metricsMap":{}},"groupedMetrics":null}`), civilDay{})
		if err != nil || len(rows) != 0 {
			t.Fatalf("rows=%v err=%v; an absent metric branch is an empty window", rows, err)
		}
	})

	t.Run("max_metrics reads the date from whichever sport block carries it", func(t *testing.T) {
		s := seriesNamed(t, "max_metrics")
		raw := json.RawMessage(`[
			{"generic":{"calendarDate":"2026-09-01","vo2MaxValue":48.0},"cycling":null,"userId":1},
			{"generic":null,"cycling":{"calendarDate":"2026-09-04","vo2MaxValue":52.0},"userId":1},
			{"generic":null,"cycling":null,"userId":1}]`)
		rows, err := s.extract(raw, civilDay{})
		if err != nil {
			t.Fatalf("extract: %v", err)
		}
		if len(rows) != 2 {
			t.Fatalf("rows = %d, want 2 (the entry with no dated block is dropped, not stored under a guess)", len(rows))
		}
		if rows[0].id != "2026-09-01" || rows[1].id != "2026-09-04" {
			t.Fatalf("rows = %+v", rows)
		}
	})

	t.Run("sleep_detail keys on dailySleepDTO.calendarDate", func(t *testing.T) {
		s := seriesNamed(t, "sleep_detail")
		rows, err := s.extract(json.RawMessage(`{"dailySleepDTO":{"calendarDate":"2026-09-06","sleepTimeSeconds":1},"sleepLevels":[]}`), mustParseCivilDay("2026-09-06"))
		if err != nil || len(rows) != 1 || rows[0].id != "2026-09-06" {
			t.Fatalf("rows=%+v err=%v", rows, err)
		}
		empty, err := s.extract(json.RawMessage(`{"dailySleepDTO":null}`), mustParseCivilDay("2026-09-06"))
		if err != nil || len(empty) != 0 {
			t.Fatalf("a night with no recorded sleep must extract nothing: rows=%v err=%v", empty, err)
		}
	})

	t.Run("training_readiness falls back to the requested day", func(t *testing.T) {
		s := seriesNamed(t, "training_readiness")
		rows, err := s.extract(json.RawMessage(`[{"score":72}]`), mustParseCivilDay("2026-09-06"))
		if err != nil || len(rows) != 1 || rows[0].id != "2026-09-06" {
			t.Fatalf("rows=%+v err=%v", rows, err)
		}
		empty, err := s.extract(json.RawMessage(`[]`), mustParseCivilDay("2026-09-06"))
		if err != nil || len(empty) != 0 {
			t.Fatalf("an empty readiness list must extract nothing: rows=%v err=%v", empty, err)
		}
	})

	t.Run("a malformed body is reported, not stored", func(t *testing.T) {
		s := seriesNamed(t, "steps")
		if _, err := s.extract(json.RawMessage(`{"error":"Bad Request","message":"too wide"}`), civilDay{}); err == nil {
			t.Fatal("an error envelope where an array was expected must surface as an extraction error")
		}
	})
}

